INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "王凝（虢州司户参军）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "欧阳修所述五代人物，家在青齐之间，曾任虢州司户参军，因病死于任上。其妻李氏携幼子和遗骸返乡的故事见《新五代史》，并被《资治通鉴》引入史论。具体生卒年未载；未与李崧案中的同名人合并。", "biography": null, "status": "draft", "id": "870009ac-f1e2-531c-8c36-107322d9996b"}, {"name": "李氏（王凝妻）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "欧阳修记述的虢州司户参军王凝之妻，姓名未详。丈夫死后，她携幼子和遗骸归乡，在开封旅舍遭拒宿并被拉扯，随后自断手臂，得到官府救助。该故事源于欧阳修所见五代笔记，具体发生年未载，保留转述性质。", "biography": null, "status": "draft", "id": "b2ad2485-2b4c-5b54-a246-95f2cc369389"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

